// Parse RSS items, filter by age, dedupe within this batch
const MAX_AGE_HOURS = 48;
const BATCH_SIM_THRESHOLD = 0.5;
const cutoff = Date.now() - (MAX_AGE_HOURS * 60 * 60 * 1000);

const STOP = new Set(['the','and','for','with','from','that','this','have','will','been','were','they','their','what','when','where','which','about','into','more','than','also','after','before','over','very','just','then','them','only','your','space','says','have','some','plans','plan','wants','want','first','next','last','best','most','many','will','also','more']);

function normalize(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokens(t) {
  return new Set(normalize(t).split(' ').filter(w => w.length >= 3 && !STOP.has(w)));
}

function overlapCoef(a, b) {
  const ta = tokens(a);
  const tb = tokens(b);
  if (ta.size === 0 || tb.size === 0) return 0;
  const intersection = [...ta].filter(x => tb.has(x)).length;
  return intersection / Math.min(ta.size, tb.size);
}

function canonicalUrl(u) {
  try {
    const url = new URL(u);
    return (url.origin + url.pathname).toLowerCase().replace(/\/$/, '');
  } catch (e) { return (u || '').toLowerCase(); }
}

const seenUrls = new Set();
const items = [];

for (const item of $input.all()) {
  const pubDate = new Date(item.json.pubDate || item.json.isoDate || item.json.date);
  if (isNaN(pubDate.getTime()) || pubDate.getTime() <= cutoff) continue;

  const url = canonicalUrl(item.json.link);
  if (seenUrls.has(url)) continue;

  const title = item.json.title || '';
  const dup = items.find(i => overlapCoef(i.json.title, title) >= BATCH_SIM_THRESHOLD);
  if (dup) continue;

  seenUrls.add(url);
  items.push({
    json: {
      title,
      link: item.json.link,
      pubDate: pubDate.toISOString(),
      source: item.json._feedName || 'unknown',
      snippet: (item.json.contentSnippet || item.json.content || '').substring(0, 500)
    }
  });
}

return items;

// Skip topics already covered in the last 28 days
const RECENT_DAYS = 28;
const RECENT_SIM_THRESHOLD = 0.5;

const STOP = new Set(['the','and','for','with','from','that','this','have','will','been','were','they','their','what','when','where','which','about','into','more','than','also','after','before','over','very','just','then','them','only','your','space','says','have','some','plans','plan','wants','want','first','next','last','best','most','many','will','also','more']);

function normalize(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

function tokens(t) {
  return new Set(normalize(t).split(' ').filter(w => w.length >= 3 && !STOP.has(w)));
}

function overlapCoef(a, b) {
  const ta = tokens(a);
  const tb = tokens(b);
  if (ta.size === 0 || tb.size === 0) return 0;
  const intersection = [...ta].filter(x => tb.has(x)).length;
  return intersection / Math.min(ta.size, tb.size);
}

const supabaseUrl = 'https://gyggbhepbfocvaeyemuu.supabase.co';
const anonKey = 'YOUR_SUPABASE_ANON_KEY';
const cutoff = new Date(Date.now() - RECENT_DAYS * 24 * 60 * 60 * 1000).toISOString();
const headers = { apikey: anonKey, Authorization: `Bearer ${anonKey}` };

let articles = [];
let runs = [];

try {
  articles = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/articles?created_at=gte.${cutoff}&select=title,seo_keyword`,
    headers,
    json: true
  }) || [];
} catch (e) {
  console.log('Articles fetch failed:', e.message);
}

try {
  runs = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/pipeline_runs?created_at=gte.${cutoff}&status=eq.drafting&select=source_title`,
    headers,
    json: true
  }) || [];
} catch (e) {
  console.log('Pipeline runs fetch failed:', e.message);
}

// Block on already-created articles or items mid-draft.
// 'discovered' and 'filtered_out' pipeline_runs are NOT blocking.
const recentTitles = [
  ...articles.map(a => a.title).filter(Boolean),
  ...runs.map(r => r.source_title).filter(Boolean)
];

const fresh = [];
let skipped = 0;
for (const item of $input.all()) {
  const title = item.json.title;
  const match = recentTitles.find(t => overlapCoef(title, t) >= RECENT_SIM_THRESHOLD);
  if (match) {
    console.log(`Skip recent dup: "${title}" ~ "${match}"`);
    skipped++;
    continue;
  }
  fresh.push(item);
}

console.log(`Filter Recent Topics: kept ${fresh.length}, skipped ${skipped} recent dups`);
return fresh;

// Build a Filter Agent request for EACH item that came through Log Discovery.
// Pair the Log Discovery response (which has pipeline_run_id) with the upstream
// RSS data (which has the snippet) by source_url.
const logResponses = $input.all();
const rssItems = $('Filter Recent Topics').all();

const rssByUrl = {};
for (const r of rssItems) {
  rssByUrl[r.json.link] = r.json;
}

const systemPrompt = `You are the editorial filter for colonizer.space, a publication focused on humans living and working in space. Score each story 0.0-1.0 for relevance.

SCORE HIGH (0.7-1.0):
- Space station construction/operations/commercial stations
- Lunar/Mars surface habitat design, construction, ISRU
- Space tourism milestones (bookings, flights, hotels)
- Launch vehicle developments directly enabling colonization
- In-space manufacturing, data centers, infrastructure
- Space economy: funding, contracts, commercial milestones
- Policy/regulation directly affecting commercial space settlement
- Life support, radiation protection, closed-loop systems

SCORE LOW (0.0-0.3):
- Pure astronomy/astrophysics with no settlement angle
- Earth-observation satellite launches (routine)
- Military/classified programs (unless dual-use)

SCORE MEDIUM (0.4-0.6):
- Rocket launches (routine but from key players)
- NASA budget/policy (indirect enabler)

Return JSON: { "score": 0.85, "reasoning": "...", "suggested_section": "moon|mars|orbit|rockets|tech|economy|players", "suggested_angle": "brief phrase" }`;

return logResponses.map(logResp => {
  const url = logResp.json.source_url;
  const rss = rssByUrl[url] || {};
  return {
    json: {
      requestBody: {
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 1024,
        system: systemPrompt,
        messages: [{
          role: 'user',
          content: `Score this story for colonizer.space relevance:\n\nTitle: ${rss.title || logResp.json.source_title}\nSource: ${rss.source || logResp.json.source_domain}\nURL: ${url}\nSnippet: ${rss.snippet || ''}`
        }]
      },
      pipeline_run_id: logResp.json.id
    }
  };
});

// Parse each Filter Agent response, sort by score, mark TOP N as passing.
const MIN_SCORE = 0.6;
const MAX_DRAFTS_PER_BATCH = 2;

const responses = $input.all();
const prepInputs = $('Prepare Filter Input').all();
const logResponses = $('Log Discovery').all();

const items = responses.map((respItem, i) => {
  const content = respItem.json.content?.[0]?.text || '{}';
  let parsed;
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
  } catch (e) {
    parsed = { score: 0, reasoning: 'Failed to parse filter response' };
  }

  const log = logResponses[i]?.json || {};
  const prep = prepInputs[i]?.json || {};

  return {
    json: {
      ...parsed,
      original_title: log.source_title,
      original_url: log.source_url,
      pipeline_run_id: prep.pipeline_run_id || log.id,
      score: parsed.score || 0
    }
  };
});

// Sort by score descending, then mark the top N (above MIN_SCORE) as passing
const sorted = [...items].sort((a, b) => (b.json.score || 0) - (a.json.score || 0));
const passingIds = new Set(
  sorted
    .filter(it => (it.json.score || 0) >= MIN_SCORE)
    .slice(0, MAX_DRAFTS_PER_BATCH)
    .map(it => it.json.pipeline_run_id)
);

for (const item of items) {
  item.json.passes_filter = passingIds.has(item.json.pipeline_run_id);
}

return items;

// Extract text from each fetched HTML page; pair with the upstream Parse Filter
// Score item using index (only items with passes_filter=true reach this node).
const pages = $input.all();
const passing = $('Parse Filter Score').all().filter(it => it.json.passes_filter);

return pages.map((page, i) => {
  const html = page.json.data || page.json.body || '';
  const text = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 8000);

  const meta = passing[i]?.json || {};

  return {
    json: {
      source_text: text,
      original_url: meta.original_url,
      original_title: meta.original_title,
      suggested_section: meta.suggested_section,
      suggested_angle: meta.suggested_angle,
      pipeline_run_id: meta.pipeline_run_id
    }
  };
});

// Build a Writer Agent request for EACH item from Extract Source Text.
const systemPrompt = "You are the staff writer for colonizer.space.

VOICE: Authoritative, technical, forward-leaning. You write like a Bloomberg space-desk reporter with an engineering background. No hype words. No hedging. State facts. Analyze implications. Be specific about timelines, numbers, players.

STRUCTURE:
- Headline: Declarative, specific, 6-12 words. No clickbait.
- Subtitle: One sentence expanding the headline.
- Lede: The news, first sentence. What happened, who did it, why it matters.
- Context: 2-3 paragraphs of background. What preceded this. Where it fits.
- Analysis: 2-3 paragraphs. What this means for the colonization timeline. What it enables or blocks. Who benefits.
- Forward look: 1 paragraph. What to watch next.

LENGTH: 500-800 words. This is a hard requirement. Count carefully.

LINK REQUIREMENTS (mandatory):
- Include exactly 1 internal link to a related topic on colonizer.space (format: [anchor text](https://colonizer.space/section/slug)). Pick a section that relates to the story (e.g., https://colonizer.space/rockets, https://colonizer.space/orbit).
- Include exactly 1 external link to the original source article being covered. Place it naturally in the context section.

SEO:
- Identify a primary keyword (2-4 words) the article should target.
- Include the keyword in the title, first paragraph, and at least one heading.
- Set seo_keyword in the output JSON.

OUTPUT FORMAT (strict JSON, no markdown wrapping):
{
  "title": "...",
  "subtitle": "...",
  "section": "moon|mars|orbit|rockets|tech|economy|players",
  "body_md": "... (full markdown article) ...",
  "excerpt": "... (160 chars for meta description) ...",
  "tags": ["tag1", "tag2"],
  "suggested_slug": "slug-here",
  "reading_time_min": 5,
  "source_urls": ["https://..."],
  "seo_keyword": "primary keyword phrase"
}";

return $input.all().map(item => {
  const d = item.json;
  return {
    json: {
      requestBody: {
        model: 'claude-sonnet-4-20250514',
        max_tokens: 4096,
        system: systemPrompt,
        messages: [{
          role: 'user',
          content: `Write a colonizer.space article based on this source material.

Source title: ${d.original_title}
Source URL: ${d.original_url}
Suggested section: ${d.suggested_section}
Suggested angle: ${d.suggested_angle}

Source text:
${d.source_text}`
        }]
      },
      pipeline_run_id: d.pipeline_run_id
    }
  };
});

// Parse each Writer response; carry pipeline_run_id forward.
const responses = $input.all();
const sources = $('Extract Source Text').all();

return responses.map((respItem, i) => {
  const content = respItem.json.content?.[0]?.text || '{}';
  let article;
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    article = JSON.parse(jsonMatch ? jsonMatch[0] : content);
  } catch (e) {
    article = { title: 'Parse failed', body_md: content };
  }

  const src = sources[i]?.json || {};

  return {
    json: {
      ...article,
      pipeline_run_id: src.pipeline_run_id,
      original_url: src.original_url
    }
  };
});

// Build an Editor Agent request for EACH parsed draft.
const systemPrompt = "You are the senior editor at colonizer.space. Review and polish this draft.

CHECK:
1. Factual claims match source material (source URLs provided)
2. No hallucinated quotes, dates, numbers, or names
3. Headline is specific and declarative
4. Lede delivers the news in sentence one
5. No filler phrases: "it remains to be seen", "only time will tell", "in a move that could", "exciting development"
6. Technical terms used correctly
7. SEO: title contains the seo_keyword, excerpt is compelling, keyword appears in first paragraph and at least one heading
8. Reading time estimate is accurate (avg 238 wpm)

QUALITY GATES (must pass or flag for review):
- Word count MUST be 500-800. If outside range, trim or expand.
- MUST contain exactly 1 internal link to colonizer.space (any section page or article). If missing, add one.
- MUST contain exactly 1 external link to the source article. If missing, add one.
- seo_keyword must be set and present in title + body.

OUTPUT: Return the complete revised article in the same JSON format. Include seo_keyword field. Add an "editor_notes" field with any flags for human review. Set status to "review" if significant issues found, "scheduled" if clean.";

return $input.all().map(item => {
  const draft = item.json;
  return {
    json: {
      requestBody: {
        model: 'claude-sonnet-4-20250514',
        max_tokens: 4096,
        system: systemPrompt,
        messages: [{
          role: 'user',
          content: 'Edit this article draft:

' + JSON.stringify(draft)
        }]
      },
      pipeline_run_id: draft.pipeline_run_id
    }
  };
});

// Parse each Editor response; carry pipeline_run_id forward.
const responses = $input.all();
const drafts = $('Parse Draft').all();

return responses.map((respItem, i) => {
  const content = respItem.json.content?.[0]?.text || '{}';
  let article;
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    article = JSON.parse(jsonMatch ? jsonMatch[0] : content);
  } catch (e) {
    article = drafts[i]?.json || { title: 'Parse failed', body_md: content };
  }

  const draft = drafts[i]?.json || {};
  return {
    json: {
      ...article,
      slug: article.suggested_slug || article.slug,
      pipeline_run_id: draft.pipeline_run_id,
      source_urls: article.source_urls || (draft.original_url ? [draft.original_url] : [])
    }
  };
});

// Pair each Check Press Photos response with its article (by index).
const results = $input.all();
const articles = $('Parse Edited Article').all();

return results.map((res, i) => {
  const article = articles[i]?.json || {};
  const photos = Array.isArray(res.json) ? res.json : [];

  if (photos.length > 0) {
    const photo = photos[0];
    return {
      json: {
        ...article,
        cover_image_url: photo.url,
        cover_image_alt: photo.alt_text || article.title,
        cover_image_credit: photo.credit,
        has_cover: true
      }
    };
  }

  return { json: { ...article, has_cover: false } };
});

// Pair each Unsplash result with the corresponding no-cover article (by index).
const results = $input.all();
const noCover = $('Merge Press Photo').all().filter(it => !it.json.has_cover);

return results.map((res, i) => {
  const article = noCover[i]?.json || {};
  const photo = res.json.results?.[0];

  if (photo) {
    return {
      json: {
        ...article,
        cover_image_url: photo.urls?.regular || photo.urls?.full,
        cover_image_alt: photo.alt_description || article.title,
        cover_image_credit: `Photo by ${photo.user?.name} on Unsplash`
      }
    };
  }

  return { json: article };
});

// Build the RSS feed list for iteration
const feeds = [
  { url: 'https://spacenews.com/feed/', name: 'SpaceNews' },
  { url: 'https://arstechnica.com/space/feed/', name: 'Ars Technica Space' },
  { url: 'https://www.nasaspaceflight.com/feed/', name: 'NASASpaceFlight' },
